class Solution:
    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:
        candidates.sort()
        res, path = [], []

        def dfs(start, remain):
            if remain == 0:
                res.append(path[:])
                return
            for i in range(start, len(candidates)):
                if candidates[i] > remain:      # 排过序，后面的只会更大
                    break
                path.append(candidates[i])
                dfs(i, remain - candidates[i])  # 还从 i 开始：可以重复选
                path.pop()

        dfs(0, target)
        return res

class Solution:
    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:
        def dfs(i, remain):
            if remain == 0:
                return [[]]
            if i == len(candidates) or remain < 0:
                return []
            c = candidates[i]
            return [[c] + rest for rest in dfs(i, remain - c)] + dfs(i + 1, remain)
        return dfs(0, target)

